"""EU AI Act Article 50 — transparency and output labeling.

Every response object leaving the pipeline MUST carry this disclosure block,
and every user interface MUST render it. The UI layer (``src/crag/ui/app.py``)
enforces the visible banner; this module is the single source of the wording
and the machine-readable flags.
"""

from __future__ import annotations

from datetime import datetime, timezone

DISCLOSURE_TEXT = (
    "You are interacting with an AI system. This response was generated by an "
    "artificial intelligence and may contain errors. It was synthesized "
    "exclusively from a local, offline snapshot of Wikipedia and has been "
    "automatically fact-checked against that same snapshot."
)


def build_disclosure(generator_model: str) -> dict:
    """Machine-readable Article 50 label attached to every pipeline result."""
    return {
        "ai_generated": True,
        "disclosure_text": DISCLOSURE_TEXT,
        "regulation": "EU AI Act, Article 50 (transparency obligations)",
        "risk_classification": "limited-risk / GPAI deployer",
        "generator_model": generator_model,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
    }
